{
  "name": "opencode-switchman",
  "version": "1.2.0",
  "description": "OpenCode orchestration plugin: six-lane shell matrix dispatch (hard ROUTE_META validation / breaker self-healing / probes / three-pool quota awareness / cost-aware tiebreaker)",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/mrzturn/opencode-switchman.git"
  },
  "homepage": "https://github.com/mrzturn/opencode-switchman#readme",
  "bugs": {
    "url": "https://github.com/mrzturn/opencode-switchman/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "multi-model",
    "orchestration",
    "subagent",
    "routing",
    "quota-aware"
  ],
  "type": "module",
  "main": "./dist/opencode-switchman.js",
  "bin": {
    "opencode-switchman": "./dist/update-cli.js"
  },
  "exports": {
    ".": "./dist/opencode-switchman.js",
    "./server": "./dist/opencode-switchman.js",
    "./tui": "./dist/opencode-switchman-tui.js"
  },
  "files": [
    "dist",
    "skills"
  ],
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "gen:shells": "bun scripts/gen-shells.ts",
    "gen:capability": "bun scripts/gen-capability-default.ts",
    "build": "bun run gen:shells && bun scripts/gen-version.ts && bun build src/index.ts --target=node --format=esm --outfile=dist/opencode-switchman.js && bun build src/doctor-cli.ts --target=node --format=esm --outfile=dist/switchman-doctor.js && bun build src/config-cli.ts --target=node --format=esm --outfile=dist/switchman-config.js && bun scripts/build-tui.ts && cp scripts/update-cli.mjs dist/update-cli.js",
    "prepublishOnly": "bun install --frozen-lockfile && bun run build && bun test",
    "pack": "bun run build && npm pack",
    "mode:local": "bun run build && bun scripts/plugin-mode.ts local",
    "mode:prod": "bun scripts/plugin-mode.ts prod",
    "deploy": "bun run mode:local"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "latest",
    "@opentui/core": ">=0.4.5",
    "@opentui/solid": "0.4.5",
    "@types/bun": "latest",
    "solid-js": "1.9.10",
    "typescript": "latest"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.4.5",
    "@opentui/solid": ">=0.4.5"
  },
  "peerDependenciesMeta": {
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    }
  }
}

{
  "name": "db-query-skill",
