  "description": "pi 技能：数据库只读查询核验（MySQL / Redis）",
  "engines": {
    "node": ">=18"
  },
  "type": "commonjs",
  "scripts": {
    "test": "node --test tests/*.test.js",
    "setup": "bash scripts/setup.sh"
  },
  "dependencies": {
    "dotenv": "16.6.1",
    "mysql2": "3.12.0",
    "redis": "4.7.1"
  },
  "devDependencies": {}
}
